# Lesson 3: opening. A light reminder of lesson 2, then the material that continues it.
SL.append(dict(id='s-title', title='פתיחה', kind='title', part=None, h='מכפיל, שחקנים ושווקים', body='', cls='', kick=None))

S('s-recap3', 'תזכורת: מפגש 2', 'תזכורת קלה: ארבע הפוזיציות של מפגש 2',
  '<p class="lead">' + TX('במפגש 2 בנינו, ליחידה אחת של מניה, את התזרים ואת הרווח של ארבע פוזיציות. מחיר מימוש (K) הוא המחיר שנקבע בחוזה, $S_{T}$ הוא המחיר בפקיעה, ו-$c$ ו-$p$ הן הפרמיות של Call ושל Put.') + '</p>'
  + TABLES(['פוזיציה', 'מי מחויב', 'תזרים (Payoff)', 'רווח (P&L)', 'נקודת איזון', 'דוגמה: K = 100, c = 8, p = 6'], [
      ['קונה Call (Long Call)', 'לא מחויב: זכות לקנות', '$max(S_{T} − K, 0)$', 'Payoff − c', '$K + c$', 'מחיר 130: $30 − 8 = 22$'],
      ['כותב Call (Short Call)', 'חייב למכור ב-K', '$−max(S_{T} − K, 0)$', 'Payoff + c', '$K + c$', 'מחיר 130: $−30 + 8 = −22$'],
      ['קונה Put (Long Put)', 'לא מחויב: זכות למכור', '$max(K − S_{T}, 0)$', 'Payoff − p', '$K − p$', 'מחיר 70: $30 − 6 = 24$'],
      ['כותב Put (Short Put)', 'חייב לקנות ב-K', '$−max(K − S_{T}, 0)$', 'Payoff + p', '$K − p$', 'מחיר 70: $−30 + 6 = −24$']])
  + '<div class="row eq2 top" style="margin-top:10px">' + BAND('dg', 'היום מתרגמים את זה לכסף: חוזה אחד מתייחס להרבה יחידות, ולכן כופלים במכפיל (Multiplier).', 5)
  + MEME('cool', 'אני אחרי מפגש 2', 'ארבע פוזיציות, ואף אחת לא מבלבלת אותי', 6) + '</div>', kick='לפני שמתחילים · תזכורת על מפגש 2')

MCS('m-warm3', 'חימום: שלוש שאלות ממפגש 2', 'חימום ממפגש 2: שלוש שאלות', [
    mc('qw31', 'משקיע קנה אופציית רכש (Long Call) על מניה, במחיר מימוש (K) של 100 ש״ח, ושילם פרמיה (c) של 8 ש״ח. בפקיעה המניה נסחרת ב-115 ש״ח. <b>נדרש:</b> מה הרווח שלו?', ['7 ש״ח', '15 ש״ח', '8 ש״ח', 'הפסד של 8 ש״ח'], 0, '$max(115 − 100, 0) − 8 = 7$.', rem='Long Call: רווח = $max(S_{T} − K, 0) − c$.'),
    mc('qw33', 'משקיע קנה אופציית מכר (Long Put) על מניה, במחיר מימוש (K) של 60 ש״ח, ושילם פרמיה (p) של 5 ש״ח. בפקיעה המניה נסחרת ב-70 ש״ח. <b>נדרש:</b> מה הרווח או ההפסד שלו?', ['הפסד של 5 ש״ח', 'רווח של 5 ש״ח', 'הפסד של 10 ש״ח', 'אפס'], 0, 'במחיר 70 אין טעם למכור ב-60, ולכן לא מממשים. התזרים 0, וההפסד הוא הפרמיה: $0 − 5 = −5$.', rem='Long Put: רווח = $max(K − S_{T}, 0) − p$.'),
    mc('qw32', 'משקיעה כתבה (מכרה) אופציית מכר (Short Put) על מניה, במחיר מימוש (K) של 50 ש״ח, וקיבלה פרמיה (p) של 4 ש״ח. <b>נדרש:</b> מהי נקודת האיזון שלה?', ['46 ש״ח', '54 ש״ח', '50 ש״ח', '4 ש״ח'], 0, '$K − p = 50 − 4 = 46$. מתחת ל-46 היא מפסידה.', rem='נקודת איזון של Put: $K − p$.')])

ROUTE = [(1, 'מכפיל, אירופאית ואמריקאית, Swap', 'נקודות ומכפיל, מתי מותר לממש, ועסקת החלפה', 'כ-45 דקות'),
         (2, 'השחקנים', 'מגדר (Hedger), ביטחונות וספקולנט (Speculator)', 'כ-30 דקות'),
         (3, 'היכן זה נסחר', 'שיקגו, תל אביב ושוק מעבר לדלפק', 'כ-20 דקות'),
         (4, 'מקרה בוחן: דלק סילוני', 'חברת תעופה, בתרגילי אקסל', 'כ-25 דקות'),
         (5, 'תרגילים מסכמים למפגש 3', 'חישובים, עם רמזים ופתרונות', 'כ-20 דקות'),
         (6, 'לבית', 'שאלות רב ברירה ותרגילי אקסל', 'עבודה עצמית')]
S('s-route', 'מסלול המפגש', 'המסלול של מפגש 3',
  '<p class="lead">' + TX('שאלה אחת מלווה את המפגש: איך מתרגמים אופציה וחוזה לכסף, ומי משתמש בהם ולמה.' + (' לחצו על חלק כדי לעבור אליו.' if MODE == 'deck' else '')) + '</p><div class="route r7">'
  + ''.join(rcard(n, t, d, m, f'p-{n}') for n, t, d, m in ROUTE) + '</div>'
  + BAND('note', 'קריאה למפגש: Hull, פרק 1 (מהדורה 11), החלקים על סוגי המשתתפים בשוק, על הבורסות ועל שוק מעבר לדלפק (OTC). הדקות הן הערכה.'), kick='מפגש 3 · מכאן החומר החדש')

opener(1, 'מכפיל, אירופאית ואמריקאית, ועסקת החלפה', 'שאלת החלק: איך הופכים תוצאה ליחידה אחת לכסף?',
       ['נקודות של מדד, והמכפיל (Multiplier)', 'אקסל: מנקודות לשקלים', 'הכללים של כל הפוזיציות, בטבלה אחת', 'אירופאית, אמריקאית ועסקת החלפה (Swap)'], 45,
       note='<b>במפגש 2:</b> ארבע פוזיציות, ליחידה אחת של מניה. <b>היום:</b> חוזה אחד מתייחס להרבה יחידות, ולכן כופלים במכפיל. אחר כך: מתי מותר לממש, ועסקת החלפה.')
